/**
 * Reassemble the ownership map.
 *
 * Unclaimed cells are NOT listed, and that is deliberate. The chart needs the
 * FULL partition -- a cell with no owner is unclaimed space and is drawn as
 * such -- so the caller passes the extent's cells and this fills the gaps.
 * Deriving them beats committing them: a change to the extent cannot leave a
 * stale cell behind claiming to be unclaimed when it is not, and the file
 * stays a list of CLAIMS rather than a second copy of the lattice.
 *
 * Claims are applied second so a cell listed under a territory is never left
 * pointing at the unclaimed id, whatever the caller passed in.
 */
export function bakedOwnership(
  allCells: Iterable<string>,
  unclaimedId: string,
): Ownership {
  const ownership: Ownership = new Map();
  for (const c of allCells) ownership.set(c, unclaimedId);
  for (const t of Object.keys(CELLS)) for (const c of CELLS[t]) ownership.set(c, t);
  return ownership;
}
